exports.id=5416,exports.ids=[5416],exports.modules={65048:(a,b,c)=>{"use strict";c.d(b,{D:()=>e,c:()=>d});let d=[{slug:"valve-insulation-jackets",title:"Valve Insulation Jackets",shortTitle:"Valves",image:"/img/applications/valve-insulation-jackets.webp",description:"Custom removable insulation jackets for industrial valves used in steam, hot oil, gas, and high-temperature process lines.",sections:[{heading:"Heat Loss Problem in Industrial Valves",image:"/img/applications/valve-problem.webp",text:"Industrial valves are one of the most common sources of exposed heat loss in steam and process systems. Because valve bodies, bonnets, and actuated assemblies have irregular shapes, standard pipe insulation often leaves gaps. These exposed areas increase fuel consumption, raise ambient temperature, and create burn hazards for operators.",points:["High surface temperature around valve body","Continuous radiant heat loss","Operator safety risk","Difficult access with fixed insulation"]},{heading:"Custom Removable Valve Jacket Solution",image:"/img/applications/valve-solution.webp",text:"Our removable valve insulation jackets are custom fabricated according to valve size, shape, temperature, and access points. The jacket can be removed during inspection or maintenance and reused again without damaging the insulation.",points:["Custom fit for valve geometry","Easy opening for maintenance","Reusable insulation system","Improves energy efficiency"]},{heading:"Common Valve Applications",image:"/img/applications/valve-applications.webp",text:"Valve insulation jackets are suitable for steam valves, control valves, gate valves, globe valves, pressure reducing valves, and high-temperature process valves used in industrial plants.",points:["Steam valves","Control valves","Gate and globe valves","Hot oil system valves"]},{heading:"Technical Construction",image:"/img/applications/valve-technical.webp",text:"Each valve jacket is manufactured using high-temperature fabric, insulation core, and secure closure systems. Material selection depends on temperature, indoor/outdoor conditions, and chemical exposure.",points:["Silicon coated fiberglass outer layer","Glass wool, rock wool, or ceramic wool core","Velcro, belt, SS hook, or SS spring closure","Custom thickness available"]}]},{slug:"flange-insulation-covers",title:"Flange Insulation Covers",shortTitle:"Flanges",image:"/img/applications/flange-insulation-covers.webp",description:"Removable flange insulation covers designed to reduce heat loss from bolted pipe joints and improve plant safety.",sections:[{heading:"Why Flanges Need Insulation Covers",image:"/img/applications/flange-problem.webp",text:"Flanges are often left exposed because maintenance teams need regular access to bolts and gaskets. However, exposed flanges create major heat loss points in steam, thermal oil, and process piping systems.",points:["Heat escapes from bolted joints","High surface temperature around flange area","Energy loss from uncovered connections","Burn hazard near maintenance zones"]},{heading:"Removable Cover for Easy Access",image:"/img/applications/flange-solution.webp",text:"Our flange covers are designed for fast removal and reinstallation. This allows maintenance teams to inspect bolts, gaskets, and leakage points without destroying insulation.",points:["Quick removal during shutdown","Reusable after inspection","Custom diameter and thickness","Suitable for hot pipelines"]},{heading:"Industrial Use Areas",image:"/img/applications/flange-applications.webp",text:"Flange insulation covers are widely used in power plants, oil and gas refineries, chemical plants, textile mills, food processing units, and fertilizer plants.",points:["Steam line flanges","Thermal oil piping","Process pipe connections","Heat exchanger joints"]},{heading:"Material and Closure Options",image:"/img/applications/flange-technical.webp",text:"Flange covers can be manufactured with fiberglass fabric, aluminum laminated fiberglass, ceramic cloth, and high-temperature insulation core depending on site conditions.",points:["Weather-resistant outer layer","High-density insulation core","SS wire, hooks, or Velcro closure","Custom tagging available"]}]},{slug:"pump-insulation-covers",title:"Pump Insulation Covers",shortTitle:"Pumps",image:"/img/applications/pump-insulation-covers.webp",description:"Custom pump insulation jackets for hot oil pumps, steam pumps, and process pumps operating at elevated temperatures.",sections:[{heading:"Heat Loss Around Pump Bodies",image:"/img/applications/pump-problem.webp",text:"Pump casings handling hot fluids can release continuous radiant heat into the plant area. This increases room temperature, creates safety risks, and reduces process energy efficiency.",points:["Exposed pump casing heat loss","Hot surface safety risk","Higher ambient temperature","Energy loss from process systems"]},{heading:"Custom Pump Jacket Design",image:"/img/applications/pump-solution.webp",text:"Our pump insulation covers are designed around pump shape, inspection points, coupling area, and maintenance requirements. The jacket allows easy removal without affecting pump servicing.",points:["Custom fit for pump casing","Access for inspection","Reusable after maintenance","Improves heat retention"]},{heading:"Suitable Pump Applications",image:"/img/applications/pump-applications.webp",text:"Pump insulation jackets are suitable for hot oil pumps, process pumps, chemical transfer pumps, steam system pumps, and high-temperature fluid handling equipment.",points:["Hot oil pumps","Chemical process pumps","Steam system pumps","Thermal fluid pumps"]},{heading:"Performance Benefits",image:"/img/applications/pump-technical.webp",text:"By reducing radiant heat from pump surfaces, insulation covers support energy savings, worker protection, and better thermal stability in the process line.",points:["Reduced radiant heat loss","Improved personnel protection","Lower operating cost","Long service life"]}]},{slug:"turbine-insulation-jackets",title:"Turbine Insulation Jackets",shortTitle:"Turbines",image:"/img/applications/turbine-insulation-jackets.webp",description:"High-temperature removable turbine insulation jackets for power plants, utilities, and industrial energy systems.",sections:[{heading:"Thermal Loss in Turbine Systems",image:"/img/applications/turbine-problem.webp",text:"Turbines operate at high temperatures and require effective insulation to maintain efficiency. Exposed turbine casings, covers, and joints can release large amounts of heat into the surrounding area.",points:["High casing temperature","Energy loss from turbine body","Unsafe maintenance area","Reduced thermal efficiency"]},{heading:"Engineered Turbine Jacket Solution",image:"/img/applications/turbine-solution.webp",text:"Our turbine insulation jackets are manufactured in removable sections for easy handling, inspection, and reinstallation. Each section is designed according to turbine geometry and site requirements.",points:["Segmented removable design","High-temperature material selection","Custom pattern fabrication","Maintenance-friendly access"]},{heading:"Power Plant Applications",image:"/img/applications/turbine-applications.webp",text:"These jackets are suitable for steam turbines, gas turbines, turbine casings, expansion joints, covers, and associated high-temperature systems in power generation plants.",points:["Steam turbines","Gas turbines","Turbine casing covers","Power generation systems"]},{heading:"Industrial Advantages",image:"/img/applications/turbine-technical.webp",text:"Turbine insulation jackets help reduce heat radiation, improve safety, support better energy performance, and allow planned maintenance without insulation waste.",points:["Improved heat retention","Reduced operator exposure","Reusable during overhauls","Heavy-duty construction"]}]},{slug:"generator-heat-shields",title:"Generator Heat Shields",shortTitle:"Generators",image:"/img/applications/generator-heat-shields.webp",description:"Generator heat shields and exhaust insulation covers for Caterpillar, Jenbacher, and industrial gas generator systems.",sections:[{heading:"Generator Exhaust Heat Problem",image:"/img/applications/generator-problem.webp",text:"Gas generator exhaust systems produce very high temperatures. Without proper insulation, exhaust manifolds, bellows, silencers, and piping radiate heat into the engine room.",points:["High exhaust surface temperature","Engine room heat buildup","Burn risk near generator","Energy waste from exhaust line"]},{heading:"Custom Generator Heat Shield Solution",image:"/img/applications/generator-solution.webp",text:"Our generator heat shields are designed for exhaust components and high-temperature surfaces. Covers are removable, reusable, and suitable for continuous-duty generator operation.",points:["Custom exhaust component covers","Fast removal for service","High-temperature insulation core","Durable outer fabric"]},{heading:"Ready Stock Generator Models",image:"/img/applications/generator-applications.webp",text:"We manufacture generator insulation covers for commonly used Caterpillar and Jenbacher gas generator models, with custom manufacturing available for other models.",points:["Caterpillar G3516-A / B / C","Caterpillar G3520-C","Jenbacher JGS320 / JGS420","Jenbacher JGS616 / JGS620"]},{heading:"Engine Room Safety and Efficiency",image:"/img/applications/generator-technical.webp",text:"Generator heat shields reduce exposed hot surfaces, improve working conditions, protect nearby components, and support better engine room heat management.",points:["Reduced radiant heat","Improved worker safety","Lower engine room temperature","Export supply available"]}]},{slug:"compressor-insulation-jackets",title:"Compressor Insulation Jackets",shortTitle:"Compressors",image:"/img/applications/compressor-insulation-jackets.webp",description:"Custom removable insulation jackets for industrial compressors, gas compressors, and high-temperature compressor systems.",sections:[{heading:"Heat Control Challenge in Compressors",image:"/imges/applications/compressor-problem.webp",text:"Industrial compressors and related process equipment can generate or carry high surface temperatures. Exposed hot sections affect safety, surrounding equipment, and energy performance.",points:["High surface temperature","Unsafe access around compressor","Radiant heat exposure","Maintenance insulation damage"]},{heading:"Removable Compressor Jacket Solution",image:"/images/applications/compressor-solution.webp",text:"Our compressor insulation jackets are custom-built to match compressor casing, pipe connections, and inspection areas. The removable design supports easy maintenance without repeated insulation replacement.",points:["Custom-fitted jacket panels","Inspection-friendly design","Reusable insulation","Strong closure system"]},{heading:"Compressor Applications",image:"/img/applications/compressor-applications.webp",text:"Compressor insulation jackets are used in gas processing, chemical plants, refineries, power plants, and high-temperature industrial process systems.",points:["Gas compressors","Process compressors","Industrial compressor lines","High-temperature casing areas"]},{heading:"Operational Benefits",image:"/img/applications/compressor-technical.webp",text:"The jackets reduce heat exposure, improve operator protection, support energy savings, and maintain clean access for maintenance teams.",points:["Reduced heat radiation","Improved safety zone","Durable reusable design","Lower insulation waste"]}]},{slug:"plastic-extruder-insulation-covers",title:"Plastic Extruder Insulation Covers",shortTitle:"Plastic Extruders",image:"/img/applications/plastic-extruder-insulation-covers.webp",description:"Barrel insulation covers for plastic extruder and injection molding machines to reduce electricity consumption and stabilize process temperature.",sections:[{heading:"Energy Loss in Plastic Extruder Barrels",image:"/img/applications/extruder-problem.webp",text:"Plastic extruder barrels use electric heaters to maintain processing temperature. Without insulation, heat escapes continuously from barrel zones, increasing electricity consumption.",points:["High electricity usage","Heat loss from barrel surface","Unstable temperature zones","Operator discomfort near machine"]},{heading:"Extruder Barrel Insulation Solution",image:"/img/applications/extruder-solution.webp",text:"Our removable barrel insulation covers are designed for heating zones, clamps, sensors, and access areas. They help retain heat around the barrel and reduce heater load.",points:["Custom barrel zone covers","Cutouts for sensors and wiring","Quick removable design","Improved temperature stability"]},{heading:"Plastic Industry Applications",image:"/img/applications/extruder-applications.webp",text:"These covers are suitable for plastic extrusion lines, injection molding machines, blow molding machines, and other heated plastic processing equipment.",points:["Plastic extruder barrels","Injection molding heaters","Blow molding machines","Heating zones and bands"]},{heading:"Production Efficiency Benefits",image:"/img/applications/extruder-technical.webp",text:"Extruder insulation covers help reduce power consumption, improve workplace comfort, and support stable processing conditions for better production control.",points:["Lower electricity consumption","Reduced heat radiation","Improved process consistency","Fast ROI potential"]}]},{slug:"industrial-piping-insulation-covers",title:"Industrial Piping Insulation Covers",shortTitle:"Industrial Piping",image:"/img/applications/industrial-piping-insulation-covers.webp",description:"Removable insulation covers for steam, hot oil, gas, and high-temperature industrial piping systems.",sections:[{heading:"Heat Loss from Industrial Piping",image:"/img/applications/piping-problem.webp",text:"Industrial pipelines carrying steam, hot oil, or process fluids can lose significant heat when insulation is missing or damaged. This increases fuel cost and reduces process efficiency.",points:["Long pipe surface heat loss","Damaged or missing insulation","High fuel consumption","Unsafe hot pipe surfaces"]},{heading:"Removable Pipe Insulation Cover Solution",image:"/img/applications/piping-solution.webp",text:"Our pipe insulation covers are designed for straight pipes, bends, elbows, joints, and removable access sections. They are suitable where regular maintenance or inspection is required.",points:["Custom pipe diameter covers","Straight and bend sections","Reusable removable design","Suitable for hot service lines"]},{heading:"Common Piping Applications",image:"/img/applications/piping-applications.webp",text:"Pipe insulation covers are used in steam distribution, process heating, thermal oil systems, utility lines, and industrial production areas.",points:["Steam piping","Hot oil lines","Process pipelines","Utility distribution lines"]},{heading:"Energy Saving and Safety Value",image:"/img/applications/piping-technical.webp",text:"Proper pipe insulation reduces continuous heat loss, improves energy efficiency, protects workers, and helps maintain process temperature across the line.",points:["Reduced line heat loss","Improved process stability","Worker burn protection","Lower operating cost"]}]}];function e(a){return d.find(b=>b.slug===a)}},65169:(a,b,c)=>{let{createProxy:d}=c(39893);a.exports=d("/home/shahrukh-eng/marketing-proj/node_modules/next/dist/client/app-dir/link.js")}};